"""Effective settings of the service."""
import json
import re

KEYS = ('password', 'passwd', 'secret', 'token', 'credential')
MASK = '***'
URL = re.compile(r"^([A-Za-z][A-Za-z0-9+.-]*://[^/\s:@]+):([^@\s/]+)@")


def describe(config):
    out = {}
    for name, value in config.items():
        if any(k in name.lower() for k in KEYS):
            out[name] = MASK
        elif isinstance(value, str) and URL.match(value):
            out[name] = URL.sub(lambda m: m.group(1) + ":" + MASK + "@", value)
        else:
            out[name] = value
    return "".join(f"{n} = {v}\n" for n, v in sorted(out.items()))

